package tv.metaxy.proof;
import com.cgutman.adblib.AdbCrypto;
import java.io.*;import java.net.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** One loopback-only connection; sequential, bounded services, never a listening server. */
final class LocalAdbSession implements Closeable {
 static final int CNXN=0x4e584e43,AUTH=0x48545541,OPEN=0x4e45504f,OKAY=0x59414b4f,WRTE=0x45545257,CLSE=0x45534c43;
 private final Socket socket=new Socket();private InputStream in;private OutputStream out;private int next=1,local,remote;private final ArrayDeque<byte[]> queued=new ArrayDeque<>();private boolean closed;
 LocalAdbSession(int port)throws IOException{if(port<1024||port>65535)throw new IllegalArgumentException("Invalid local ADB port");socket.connect(new InetSocketAddress(InetAddress.getByAddress(new byte[]{127,0,0,1}),port),2000);socket.setTcpNoDelay(true);socket.setSoTimeout(60000);in=socket.getInputStream();out=socket.getOutputStream();}
 static final class Packet{final int code,a,b;final byte[] data;Packet(int c,int x,int y,byte[] z){code=c;a=x;b=y;data=z;}}
 static byte[] frame(int cmd,int a,int b,byte[] data){if(data.length>4096)throw new IllegalArgumentException("ADB payload exceeds advertised limit");int sum=0;for(byte x:data)sum+=x&255;return ByteBuffer.allocate(24+data.length).order(ByteOrder.LITTLE_ENDIAN).putInt(cmd).putInt(a).putInt(b).putInt(data.length).putInt(sum).putInt(~cmd).put(data).array();}
 static Packet readPacket(InputStream source)throws IOException{byte[] head=new byte[24];new DataInputStream(source).readFully(head);ByteBuffer b=ByteBuffer.wrap(head).order(ByteOrder.LITTLE_ENDIAN);int cmd=b.getInt(),a=b.getInt(),c=b.getInt(),size=b.getInt(),sum=b.getInt(),magic=b.getInt();if(magic!=~cmd||size<0||size>65536)throw new IOException("Invalid ADB frame");byte[] data=new byte[size];new DataInputStream(source).readFully(data);int actual=0;for(byte x:data)actual+=x&255;if(sum!=actual)throw new IOException("Invalid ADB checksum");return new Packet(cmd,a,c,data);}
 private void send(int cmd,int a,int b,byte[] data)throws IOException{out.write(frame(cmd,a,b,data));out.flush();}
 void authenticate(AdbCrypto key)throws Exception{send(CNXN,0x01000000,4096,"host::kinegra-home\0".getBytes(StandardCharsets.UTF_8));boolean signed=false;for(int n=0;n<8;n++){Packet p=readPacket(in);if(p.code==CNXN){socket.setSoTimeout(10000);return;}if(p.code!=AUTH||p.a!=1||p.data.length!=20)throw new IOException("Unexpected ADB authentication reply");if(!signed){send(AUTH,2,0,key.signAdbTokenPayload(p.data));signed=true;}else send(AUTH,3,0,key.getAdbPublicKeyPayload());}throw new IOException("ADB approval did not complete");}
 private void open(String service)throws IOException{queued.clear();closed=false;local=next++;remote=0;byte[] name=(service+'\0').getBytes(StandardCharsets.UTF_8);send(OPEN,local,0,name);Packet p;do{p=readPacket(in);}while(p.b!=local);if(p.code!=OKAY)throw new IOException("ADB service unavailable");remote=p.a;}
 private Packet receive()throws IOException{Packet p=readPacket(in);if(p.b!=local)throw new IOException("Unexpected ADB stream");if(p.code==WRTE){send(OKAY,local,p.a,new byte[0]);}else if(p.code==CLSE){closed=true;send(CLSE,local,p.a,new byte[0]);}return p;}
 private void write(byte[] data)throws IOException{send(WRTE,local,remote,data);while(true){Packet p=receive();if(p.code==OKAY)return;if(p.code==WRTE)queued.add(p.data);if(p.code==CLSE)throw new EOFException("ADB stream ended while writing");}}
 private byte[] read()throws IOException{if(!queued.isEmpty())return queued.remove();while(!closed){Packet p=receive();if(p.code==WRTE)return p.data;}throw new EOFException("ADB stream ended");}
 private void closeStream()throws IOException{if(!closed){send(CLSE,local,remote,new byte[0]);closed=true;}queued.clear();}
 String shell(String fixedCommand)throws IOException{open("shell:"+fixedCommand);ByteArrayOutputStream bytes=new ByteArrayOutputStream();while(!closed){Packet p=receive();if(p.code==WRTE){if(bytes.size()+p.data.length>16384)throw new IOException("ADB output limit exceeded");bytes.write(p.data);}}return new String(bytes.toByteArray(),StandardCharsets.UTF_8).trim();}
 private static byte[] sync(String id,int size,byte[] data){return ByteBuffer.allocate(8+data.length).order(ByteOrder.LITTLE_ENDIAN).put(id.getBytes(StandardCharsets.US_ASCII)).putInt(size).put(data).array();}
 void push(byte[] file,String fixedPath)throws IOException{if(file.length<1||file.length>4*1024*1024)throw new IOException("Unexpected helper size");open("sync:");byte[] path=(fixedPath+",33152").getBytes(StandardCharsets.UTF_8);write(sync("SEND",path.length,path));for(int at=0;at<file.length;at+=2048){byte[] part=Arrays.copyOfRange(file,at,Math.min(file.length,at+2048));write(sync("DATA",part.length,part));}write(sync("DONE",0,new byte[0]));byte[] reply=read();if(reply.length<8||reply[0]!='O'||reply[1]!='K'||reply[2]!='A'||reply[3]!='Y')throw new IOException("Helper upload was refused");write(sync("QUIT",0,new byte[0]));closeStream();}
 @Override public void close()throws IOException{socket.close();}
}
